import {highlightHtml,evidencePreview} from './report-highlight.mjs';
import {sliceCp} from './engine.mjs';
import {reportDocument,reportEscape as esc} from '../reports/report-document.mjs';
const fmt=n=>Number(n||0).toLocaleString('zh-CN');
const pct=n=>Number.isFinite(n)?(n*100).toFixed(1):'—';
const metric=(label,value,note='')=>`<div class="report-metric"><small>${esc(label)}</small><strong>${esc(value)}</strong>${note?`<em>${esc(note)}</em>`:''}</div>`;
const sourceHref=value=>{try{const u=new URL(value);return ['http:','https:'].includes(u.protocol)?u.href:null;}catch{return null;}};
export function reportHtml(report){
 const sources=report.sources||[],sections=report.sections||[],included=sections.filter(s=>s.included),sourceMap=new Map(sources.map((s,i)=>[s.id,{...s,number:i+1}])),isDemo=report.mode==='demo'||sources.some(s=>s.kind==='demo');let evidenceBudget=120;
 const scope=isDemo?'演示材料与指定对照正文':'用户提供的本地对照正文';
 const sourceRows=sources.map((s,i)=>`<tr><td style="width:7%">${i+1}</td><td><b>${esc(s.title)}</b><div class="report-source-info">${esc(s.authors?.join('、')||'作者未提供')} · ${esc(s.year||'年份未提供')}</div></td><td style="width:22%">${fmt(s.overlapChars)}<div class="report-bar"><span style="width:${Math.min(100,Math.max(0,(s.overlapChars||0)/Math.max(1,report.totalChars)*100))}%"></span></div></td></tr>`).join('');
 const summary=`<section class="report-panel"><h2 class="report-section-title">检测结果总览</h2><div class="report-metrics">${metric('文字相似占比',pct(report.ratio)+'%','实际匹配区间合并去重')}${metric('去除识别引用后',pct(report.uncitedRatio)+'%','引用识别范围有限，需核对')}${metric('参与检测字符',fmt(report.totalChars),'字母与数字，不含标点空白')}${metric('匹配字符',fmt(report.similarChars),`${report.sourceCount||0} 个命中来源 / ${sources.length} 份对照材料`)}</div><p class="report-muted">上述结果仅针对本次实际提供的材料；“未发现匹配”不代表在其他数据库或全网范围内不存在相似内容。</p></section><section class="report-panel"><h2 class="report-section-title">章节检测结果</h2><table class="report-table"><thead><tr><th style="width:42%">章节名称</th><th>检测字符</th><th>匹配字符</th><th>相似占比</th></tr></thead><tbody>${sections.map(s=>`<tr><td>${esc(s.title)}${s.included?'':' <span class="report-badge">未参与检测</span>'}</td><td>${s.included?fmt(s.totalChars):'—'}</td><td>${s.included?fmt(s.similarChars):'—'}</td><td>${s.included?pct(s.ratio)+'%':'—'}</td></tr>`).join('')}</tbody></table></section><section class="report-panel"><h2 class="report-section-title">相似来源概览</h2>${sources.length?`<table class="report-table"><thead><tr><th style="width:7%">编号</th><th>对照材料</th><th style="width:22%">命中字符</th></tr></thead><tbody>${sourceRows}</tbody></table>`:'<div class="report-empty">没有记录可展示的来源材料。</div>'}<p class="report-muted">同一正文片段可能对应多个来源，各来源命中字符不可直接相加。</p></section>`;
 const body=`<section class="report-panel report-page-break"><h2 class="report-section-title">全文标注与片段对照</h2><div class="report-legend"><span><i style="background:#efaea9"></i>实际文字匹配</span><span><i style="background:#a1d9c4"></i>匹配中的已识别引用</span><span><i style="background:#dce2eb"></i>未参与检测</span></div><p class="report-muted">正文标注保留全部实际匹配。片段对照每段最多展示 12 个代表区间、整份 HTML 最多 120 个，完整区间保留在 JSON 报告中。</p>${sections.map(s=>`<div class="${s.included?'':'report-excluded'}"><div class="report-section-head"><h3>${esc(s.title)}</h3><span>${s.included?pct(s.ratio)+'%':'未参与检测'}</span></div>${(s.paragraphs||[]).map((p,index)=>{const rows=s.included?evidencePreview(p.matches||[],Math.min(12,evidenceBudget)):[];evidenceBudget-=rows.length;return `<div class="report-paragraph"><div class="report-paragraph-header">第 ${index+1} 段${s.included&&p.matches?.length?` · ${p.matches.length} 个匹配区间`:''}</div><p class="report-text">${s.included?highlightHtml(p.text,p.matches||[]):esc(p.text)}</p>${rows.map(m=>{const source=sourceMap.get(m.sourceId);if(!source)return '';return `<div class="report-evidence"><div class="report-evidence-head"><b>来源 [${source.number}] ${esc(source.title)}</b><div class="report-source-info">${m.citationStatus==='verified_quotation'?'含已识别引用，仍需核对':'未识别为引用'} · ${esc(source.authors?.join('、')||'作者未提供')} · ${esc(source.year||'年份未提供')}</div></div><div class="report-evidence-body report-pair"><div><small>论文匹配片段</small><p class="report-text">${esc(sliceCp(p.text,...m.range))}</p></div><div><small>来源对应片段</small><p class="report-text">${esc(sliceCp(source.text,...m.sourceRange))}</p></div></div></div>`;}).join('')}</div>`;}).join('')}</div>`).join('')}</section><section class="report-panel report-page-break"><h2 class="report-section-title">对照材料与来源信息</h2>${sources.map((s,i)=>{const href=sourceHref(s.url);return `<article class="report-evidence"><div class="report-evidence-head"><h3 class="report-source-title">[${i+1}] ${esc(s.title)}</h3><div class="report-source-info">${esc(s.authors?.join('、')||'作者未提供')} · ${esc(s.year||'年份未提供')} · ${esc(s.provider||'来源未提供')}</div></div><div class="report-evidence-body"><p class="report-source-info">DOI：${esc(s.doi||'未提供')}<br>URL：${href?`<a href="${esc(href)}" rel="noreferrer noopener">${esc(s.url)}</a>`:esc(s.url||'未提供')}<br>材料类型：${s.kind==='demo'?'演示材料':'用户提供，未联网核验'}</p><p class="report-text">${esc(s.text)}</p></div></article>`;}).join('')}</section><section class="report-panel"><h2 class="report-section-title">检测口径与使用说明</h2><ol class="report-notes"><li>总相似占比 = 合并去重后的匹配字符数 ÷ 参与检测的有效正文字符数。同一字符命中多个来源只计算一次。</li><li>字符统计包含 Unicode 字母与数字，不含标点空白。仅本次确认的 ${included.length} 个章节参与计分。</li><li>引用排除规则：${esc(report.citationPolicy||'未记录，请人工核对')}。</li><li>本报告未检索在线学术数据库，不包含语义相似度、AI 率或外部数据库检测结果。不等同于知网、万方、维普检测。</li><li>报告编号仅用于定位这份 PaperKnow 记录，不代表第三方认证或官方防伪编号。修改后的正文需要重新检测，原报告数值保持不变。</li></ol></section>`;
 return reportDocument({title:report.title,type:'文本相似性检测报告',id:report.id,createdAt:report.createdAt,scope,metadata:[['学段 / 身份',report.degree||'未提供'],['原文件',report.fileName||'粘贴正文'],['报告状态',report.complete===false?'未完整完成':'比对已完成']],notice:'本地材料比对报告，未检索在线学术数据库。结果仅来自本次指定材料中的实际文字匹配，适合用于来源核对和修改参考。',summary,body,demo:isDemo});
}
